"""Tkinter application shell that owns navigation and shared services."""

import tkinter as tk

from ..admin.service import AdminService
from ..game.engine import Game
from ..storage.question_repository import QuestionRepository
from ..storage.score_repository import ScoreRepository
from ..user.models import UserService
from .admin_screen import AdminScreen
from .play_screen import PlayScreen
from .screens import EndingScreen, HelpScreen, HighScoresScreen, IntroScreen, MenuScreen


class App(tk.Tk):
    """Root window; screens are swapped in and out of the same window."""

    def __init__(self, db):
        super().__init__()
        self.title("Space Fractions")
        self.geometry("800x600")
        self.resizable(True, True)

        self.db = db
        self.db.init_schema()
        self.question_repo = QuestionRepository(self.db)
        self.score_repo = ScoreRepository(self.db)
        self.admin_service = AdminService(self.question_repo)
        self.user_service = UserService()
        self.game = None
        self._current = None
        self.show_intro()

    def _swap(self, screen_cls, *args, **kwargs):
        if self._current is not None:
            self._current.destroy()
        self._current = screen_cls(self, *args, **kwargs)
        self._current.pack(fill="both", expand=True)

    def show_intro(self):
        self._swap(IntroScreen)

    def show_menu(self):
        self._swap(MenuScreen)

    def show_help(self):
        self._swap(HelpScreen)

    def show_high_scores(self):
        self._swap(HighScoresScreen)

    def show_admin(self):
        self._swap(AdminScreen)

    def show_ending(self):
        self._swap(EndingScreen)

    def start_game(self):
        questions = self.question_repo.list_all()
        if not questions:
            from ..question.factory import default_questions
            for question in default_questions():
                self.question_repo.save(question)
            questions = self.question_repo.list_all()
        self.game = Game(questions)
        self._swap(PlayScreen)
